        "title": "同辈压力（Peer Pressure）的双刃剑：从‘社会疗法’神话到社交传染动力学",
        "subtitle": "自发模仿与自外强加——为什么政府官僚精心策划的‘积极同辈干预’往往难以持久？",
        "coreNarrative": "在传统社会认知中，‘同辈压力’（peer pressure）往往带有浓厚贬义色彩，被普遍视作引发青少年吸毒、酗酒、危险性行为等不良举动的罪魁祸首（a cause of undesirable behaviors）。然而，普利策奖得主蒂娜·罗森伯格在《加入俱乐部》（Join the Club）中提出了颠覆性假设：同辈压力是一股强大的积极力量，政府与公益组织可以通过‘社会疗法’（the social cure）调动群体动力来改变恶习。作者在书评中肯定了罗森伯格对传统公共卫生宣传的犀利批判（指出‘敢于与众不同’的禁烟口号完全违背青少年渴望合群的心理），但尖锐指出了‘社会疗法’的致命缺陷：该书充斥无关细节，未能深入探讨同辈压力的社会与生物学底层机理，且外部资助一旦中断效果便烟消云散。真正的同辈压力源于人们在日常交往中‘潜意识的自发模仿’（unconscious imitation），任何由官僚从外部人为强行干预（engineered from the outside）的同辈重组策略注定徒劳，因为无论在学校还是现实社会中，人们都坚持自主选择朋友。",
        "historicalAndEconomicContext": "反映了2010年前后行为经济学（如理查德·塞勒‘助推’理论 Nudge）与社会网络分析在公共政策领域的跨界探索热潮。公共卫生部门试图用低成本的社会动力学替代行政强制，但往往因忽视深层自发人际网络选择而陷入短期工程主义的死胡同。",
        "crossExamLinks": "与2010年Text 3（网络影响者神话与社交级联动力学）、2011年Text 4（从众心理与媒体对生活态度的无意识塑造）共同构成考研英语‘社会心理学、从众行为与人际传染网络’核心考题群落。"
