        "subtitle": "商业契约的神圣性与公共信托——当核能巨头撕毁承诺诉诸合宪性审查",
        "coreNarrative": "2002年，跨国能源巨头安特吉公司（Entergy）收购了佛蒙特州唯一的核电站——弗农的老旧核反应堆（Vermont Yankee）。作为获批收购的前置条件，安特吉签署协议承诺若在2012年牌照到期后继续运营，必须征求佛蒙特州监管机构的批准；2006年州政府追加立法规定延期须经州议会表决通过，安特吉再次予以顺从。然而此后该厂发生冷却塔局部倒塌、含致癌物氚的地下排污管泄漏等多起安全事故，安特吉更对管道问题发表误导性欺瞒陈述，激怒了佛蒙特州参议院，最终以26:4的压倒性多数否决了其延期申请。遭遇重挫的安特吉随即出尔反尔，以‘2002年协议因2006年新法而失效、且唯有联邦政府享有核事务管辖权’为由，在联邦法院起诉州法违宪。作者痛斥其背信弃义，指出契约必须信守（a deal is a deal），核电运营权乃公众信托（public trust），并呼吁联邦核管会（NRC）在审查其在其他州（如马萨诸塞州朝圣者核电站）的延期申请时，清醒认识到该公司的承诺毫无诚信价值。",
        "historicalAndEconomicContext": "反映了美国能源法领域著名的‘联邦先占权’（Federal Preemption）与州保留权力之间的张力。根据美国《原子能法》（Atomic Energy Act），联邦核管会（NRC）对核辐射安全拥有专属管辖权，但各州对电力设施的经济性、可靠性和选址土地利用保留监管权。安特吉利用这一法律灰色地带逃避州对老旧核反应堆的安全约束，引发了关于垄断企业诚信、环境安全与多层级治理边界的激烈交锋。",
